SELECT * FROM (SELECT e.event_id,'A:'||s.audit_id case_id,e.activity,e.timestamp FROM (SELECT 'A:'||audit_id||':start' event_id,'Stock Audit Started' activity,started_at timestamp,audit_id source_key FROM warehouse_audit WHERE started_at IS NOT NULL AND (1=1)) e JOIN warehouse_audit s ON s.audit_id=e.source_key WHERE s.audit_id IS NOT NULL UNION ALL SELECT e.event_id,'A:'||s.audit_id case_id,e.activity,e.timestamp FROM (SELECT 'A:'||audit_id||':complete' event_id,'Stock Audit Completed' activity,completed_at timestamp,audit_id source_key FROM warehouse_audit WHERE completed_at IS NOT NULL AND (1=1)) e JOIN warehouse_audit s ON s.audit_id=e.source_key WHERE s.audit_id IS NOT NULL) ORDER BY case_id,timestamp,event_id;
